using System;using System.IO;using System.IO.Compression;using System.Net;using System.Net.Http;using System.Net.Http.Headers;using System.Text;using System.Collections.Generic;using System.Globalization;using OpenMetaverse.StructuredData;
static class Host {
 public static int Level,Number,Ticks,Flags,Mode;public static int? Code;public static long? Length;public static string Fail,Wire;public static List<string> Events;public static Timer Current;
 public static void Hit(string text){Events.Add(text);string tag=text.Split(':')[0];bool match=Array.IndexOf(Fail.Split('+'),tag)>=0;if(tag=="debug"){if(Fail=="debug-final"&&text.Contains(" took "))match=true;if(Fail=="debug-catch"&&text.StartsWith("debug:[WEB UTIL]: Exception"))match=true;if(Fail=="debug-failed"&&text.StartsWith("debug:[LOGHTTP]: request"))match=true;}if(match){if((Flags&16)!=0)throw new HttpRequestException(Fail,null,Code.HasValue?(HttpStatusCode?)Code.Value:null);throw new InvalidOperationException(Fail);}}
 public static string H(string s){if(s==null)return "-";if(s.Length==0)return ".";var b=new StringBuilder(s.Length*4);foreach(char c in s)b.Append(((int)c&255).ToString("x2")).Append(((int)c>>8).ToString("x2"));return b.ToString();}
 public static string Hex(byte[] b)=>Convert.ToHexString(b).ToLowerInvariant();
 public static string Reply()=>((Mode>>8)%7) switch {1=>"true",2=>"false",3=>"not json",4=>"null",5=>"[]",6=>"<llsd><map><key>success</key><boolean>true</boolean></map></llsd>",_=>"{\"success\":true,\"reason\":\"ok é😀\"}"};
 public static OSDMap Data()=>new(){{"name",OSD.FromString("é😀\r\n<&>")},{"count",OSD.FromInteger(47)},{"nested",new OSDArray{OSD.FromBoolean(true),OSD.FromString("")}}};
 public static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;string line;while((line=Console.ReadLine())!=null){var a=line.Split(' ');Level=int.Parse(a[0]);Number=int.Parse(a[1]);Ticks=int.Parse(a[2]);Flags=int.Parse(a[3]);Mode=int.Parse(a[4]);Length=a[5]=="-"?null:long.Parse(a[5]);Fail=a[6];Code=a[7]=="-"?null:int.Parse(a[7]);Events=new();Wire=null;Current=null;OSDMap result=null;string status="O";try{result=WebUtil.ServiceOSDRequest("http://example.test/path",(Flags&1)!=0?null:Data(),"POST",1234,(Flags&2)!=0,(Flags&4)!=0,(Flags&8)!=0);}catch(Exception e){status="E:"+e.GetType().FullName+":"+H(e.Message);}Console.WriteLine(status+"|"+Number+"|"+Level+"|"+H(string.Join("\n",Events))+"|"+(result==null?"-":Hex(Encoding.UTF8.GetBytes(OpenMetaverse.StructuredData.OSDParser.SerializeJsonString(result,true))))+"|"+H(Wire));}}
}
class Request:IDisposable {public HttpRequestMessage Inner;public Request(HttpMethod method,string url){Host.Hit("request");Inner=new HttpRequestMessage(method,url);}public HttpRequestHeaders Headers=>Inner.Headers;public HttpContent Content{get=>Inner.Content;set=>Inner.Content=value;}public void Dispose(){Host.Hit("request-close");Inner.Dispose();}}
class Client:IDisposable {public Response Send(Request r,HttpCompletionOption o){Host.Hit("send");var h=new SortedDictionary<string,string>(StringComparer.Ordinal);foreach(var p in r.Headers)h.Add(p.Key.ToLowerInvariant(),string.Join(", ",p.Value));if(r.Content!=null)foreach(var p in r.Content.Headers)h.Add(p.Key.ToLowerInvariant(),string.Join(", ",p.Value));Host.Wire=r.Inner.Method.Method+"\n"+r.Inner.RequestUri.OriginalString+"\n"+(r.Content==null?"-":Host.Hex(r.Content.ReadAsByteArrayAsync().GetAwaiter().GetResult()));foreach(var p in h)Host.Wire+="\n"+p.Key+":"+p.Value;return new Response();}public void Dispose(){Host.Hit("client-close");}}
